class PersistentLoad(pickle.Unpickler):
    def persistent_load(self, pid):
        # If it's trying to load from a dict we already have
        pid_bits = pid.split('.')
        root_bit = pid_bits[0]
        if root_bit.startswith('01a19df4'):
            try:
                return self.global_vars.get(root_bit, {})
            except:
                pass
        # Default to return empty
